package com.mealflex.payment.controller;
import com.mealflex.payment.dto.*; import com.mealflex.payment.service.PaymentService; import com.mealflex.security.UserPrincipal; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
/** Stable public route kept alongside the original /payments/methods endpoints. */
@RestController @RequestMapping("/v1/payment-methods") @RequiredArgsConstructor public class PaymentMethodController { private final PaymentService service; @GetMapping public List<PaymentMethodResponse> list(@AuthenticationPrincipal UserPrincipal p){return service.listMethods(p.getId());}@PostMapping public ResponseEntity<PaymentMethodResponse> create(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody CreatePaymentMethodRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.addMethod(p.getId(),request));}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){service.deleteMethod(p.getId(),id);return ResponseEntity.noContent().build();}}
